"""Fund slot formulas generated by scripts/generate_ul_fund_slots.py."""

from avk.model.lang import Component, if_, int_axis, keymap, on, param, prev, scen, table

SLOTS = 5


class FundSlots(Component):
    """Per-slot unit fund formulas and their policy totals."""

    REQUIRES = (
        "A_begin",
        "R_survival",
        "active_retention",
        "additions_pp",
        "allocated_pp",
        "live",
        "maturity",
        "rpu_retention",
        "to_rpu",
        "year_start",
        "allocated_topup_pp",
        "pw_pp",
        "retention_after_withdrawal",
        "topup_lock_active",
        "age",
        "policy_year",
        "policy_month",
    )
    fund_return_margin = param("fund_return_margin")
    mc_fund_return_source = param("mc_fund_return_source")
    reference_forward = scen("reference_forward")
    ret_eq_large = scen("ret_eq_large")
    ret_eq_mid = scen("ret_eq_mid")
    ret_eq_small = scen("ret_eq_small")
    ret_eq_global = scen("ret_eq_global")
    ret_gov_long = scen("ret_gov_long")
    ret_gov_short = scen("ret_gov_short")
    ret_corp_bond = scen("ret_corp_bond")
    ret_money_market = scen("ret_money_market")
    ret_gold = scen("ret_gold")
    ret_real_assets = scen("ret_real_assets")
    strategy_mode_data = table("ul_strategies/mode", axes=())
    strategy_source_slot_data = table("ul_strategies/source_slot", axes=())
    strategy_amount_data = table("ul_strategies/amount", axes=())
    strategy_target_1_data = table("ul_strategies/target_1", axes=())
    strategy_target_2_data = table("ul_strategies/target_2", axes=())
    strategy_target_3_data = table("ul_strategies/target_3", axes=())
    strategy_target_4_data = table("ul_strategies/target_4", axes=())
    strategy_target_5_data = table("ul_strategies/target_5", axes=())
    strategy_share_data = table(
        "ul_strategies/share",
        axes=(
            int_axis("strategy_year", below="clamp", above="clamp"),
            keymap("Strategy_Id", unknown="error", above="error"),
        ),
    )

    def fund_return_factor(self, t):
        """Monthly factor for the signed reserving fund return margin."""
        return (1 + self.fund_return_margin) ** (1 / 12)

    def rebalance(self, t):
        """Rebalance at the start of the policy year when target weights exist."""
        return (
            self.policy.Strategy_Mode == 0
            and self.policy.V_auto_rebalance
            and self.year_start(t)
            and self.allocation_total(t) > 0
        )

    def lifecycle_switch(self, t):
        """Update lifecycle allocation at the first step and policy-year starts."""
        return (self.policy.Strategy_Mode == 1 or self.policy.Strategy_Mode == 2) and (
            (t == 1 or self.year_start(t)) and self.live(t) and self.A_begin(t) > 0
        )

    def stp_switch(self, t):
        """A monthly transfer while active and inside the term."""
        return self.policy.Strategy_Mode >= 3 and self.live(t) and self.A_begin(t) > 0

    def strategy_year(self, t):
        """The age or remaining-term index of the lifecycle schedule."""
        return if_(
            self.policy.Strategy_Mode == 1,
            self.age(t) + 1,
            if_(
                self.policy.Strategy_Mode == 2, self.policy.Policy_Term - self.policy_year(t) + 1, 1
            ),
        )

    def strategy_share(self, t):
        """The lifecycle schedule at the current index or the level STP fraction."""
        return self.strategy_share_data[self.strategy_year(t), self.policy.Strategy_Id]

    def switch_charge_pp(self, t):
        """The charge funded from the month's gross internal switch."""
        return min(self.policy.V_switch_charge, self.switch_out_total(t))

    def switch_net_pp(self, t):
        """Proceeds of the month's switch available for reinvestment."""
        return self.switch_out_total(t) - self.switch_charge_pp(t)

    def fund_1_allocation(self, t):
        """Fund 1's share of the allocation weights."""
        return if_(
            self.allocation_total(t) > 0,
            self.policy.Fund_1_Allocation / self.allocation_total(t),
            0,
        )

    def fund_1_raw_open(self, t):
        """Opening active value of slot 1, with rebalancing when due."""
        return if_(
            t == 0 or ((self.live(t) or self.maturity(t)) and self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.fund_close_total, 0) * self.fund_1_allocation(t),
                prev(
                    self.fund_1_close,
                    self.policy.Fund_1_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_1_strategy_member(self, t):
        """Whether slot 1 belongs to the strategy basket."""
        return self.policy.Strategy_Source_Slot == 1 or self.policy.Strategy_Target_1 > 0

    def fund_1_strategy_weight(self, t):
        """Lifecycle target weight within the equity and debt basket."""
        return if_(
            self.policy.Strategy_Source_Slot == 1,
            self.strategy_share(t),
            (1 - self.strategy_share(t)) * self.policy.Strategy_Target_1,
        )

    def fund_1_strategy_change(self, t):
        """Gross lifecycle target minus the opening value in slot 1."""
        return if_(
            self.lifecycle_switch(t) and self.fund_1_strategy_member(t),
            self.strategy_value(t) * self.fund_1_strategy_weight(t) - self.fund_1_raw_open(t),
            0,
        )

    def fund_1_switch_out(self, t):
        """Value sold from slot 1, before the switch charge."""
        return if_(
            self.stp_switch(t) and self.policy.Strategy_Source_Slot == 1,
            if_(
                self.policy.Strategy_Mode == 3,
                self.fund_1_raw_open(t) * self.strategy_share(t),
                min(self.policy.Strategy_Amount, self.fund_1_raw_open(t)),
            ),
            max(-self.fund_1_strategy_change(t), 0),
        )

    def fund_1_switch_weight(self, t):
        """Share of net switch proceeds invested in slot 1."""
        return if_(
            self.lifecycle_switch(t),
            if_(
                self.lifecycle_demand(t) > 0,
                max(self.fund_1_strategy_change(t), 0) / self.lifecycle_demand(t),
                0,
            ),
            self.policy.Strategy_Target_1,
        )

    def fund_1_open(self, t):
        """Opening slot value after internal strategy transfers and their charge."""
        return if_(
            self.switch_out_total(t) > 0,
            self.fund_1_raw_open(t)
            - self.fund_1_switch_out(t)
            + self.switch_net_pp(t) * self.fund_1_switch_weight(t),
            self.fund_1_raw_open(t),
        )

    def fund_1_after_premium(self, t):
        """Slot 1 after crediting its share of allocated premiums."""
        return self.fund_1_open(t) + self.allocated_pp(t) * self.fund_1_allocation(t)

    def fund_1_topup_raw_open(self, t):
        """Opening tagged top-up balance, including its share of any rebalance."""
        return if_(
            self.policy.V_topup_on and (t == 0 or self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.topup_close_total, 0) * self.fund_1_allocation(t),
                prev(
                    self.fund_1_topup_close,
                    self.policy.Fund_1_Topup_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_1_topup_switch_out(self, t):
        """The portion of the sale made up of tagged top-up units."""
        return if_(
            self.fund_1_switch_out(t) > 0 and self.fund_1_raw_open(t) > 0,
            self.fund_1_switch_out(t) * (self.fund_1_topup_raw_open(t) / self.fund_1_raw_open(t)),
            0,
        )

    def fund_1_topup_open(self, t):
        """Opening tagged value after the same transfer and charge as other units."""
        return if_(
            self.switch_out_total(t) > 0 and self.policy.V_topup_on,
            self.fund_1_topup_raw_open(t)
            - self.fund_1_topup_switch_out(t)
            + self.switch_net_pp(t)
            * self.fund_1_switch_weight(t)
            * (self.topup_switch_out_total(t) / self.switch_out_total(t)),
            self.fund_1_topup_raw_open(t),
        )

    def fund_1_topup_after_premium(self, t):
        """Tagged top-up balance after buying new units."""
        return self.fund_1_topup_open(t) + self.allocated_topup_pp(t) * self.fund_1_allocation(t)

    def fund_1_withdrawable(self, t):
        """Slot value available for partial withdrawal."""
        return if_(
            self.topup_lock_active(t),
            max(self.fund_1_after_premium(t) - self.fund_1_topup_after_premium(t), 0),
            self.fund_1_after_premium(t),
        )

    def fund_1_withdrawal(self, t):
        """The withdrawal apportioned by the slot's unlocked holdings."""
        return if_(
            self.withdrawable_total(t) > 0,
            self.pw_pp(t) * (self.fund_1_withdrawable(t) / self.withdrawable_total(t)),
            0,
        )

    def fund_1_after_charges(self, t):
        """Slot 1 after its share of withdrawals and charges."""
        return if_(
            self.topup_lock_active(t),
            (self.fund_1_after_premium(t) - self.fund_1_withdrawal(t))
            * self.retention_after_withdrawal(t),
            self.fund_1_after_premium(t) * self.active_retention(t),
        )

    def fund_1_topup_after_charges(self, t):
        """Top-up units after deductions, valued at the opening price."""
        return self.fund_1_topup_after_premium(t) * if_(
            self.topup_lock_active(t), self.retention_after_withdrawal(t), self.active_retention(t)
        )

    def fund_1_market_return(self, t):
        """Monthly asset-mix return and fund alpha of slot 1."""
        return (
            self.policy.Fund_1_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_1_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_1_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_1_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_1_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_1_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_1_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_1_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_1_W_gold * self.ret_gold[t]
            + self.policy.Fund_1_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_1_Alpha) ** (1 / 12) - 1)

    def fund_1_growth_rate(self, t):
        """Gross investment return for slot 1."""
        return self.fund_1_market_return(t) * self.live(t)

    @on("reserving", overrides="fund_1_growth_rate")
    def fund_1_reserving_growth_rate(self, t):
        """Slot 1's return including the reserving margin."""
        return ((1 + self.fund_1_market_return(t)) * self.fund_return_factor(t) - 1) * self.live(t)

    @on("mc", overrides="fund_1_growth_rate")
    def fund_1_mc_growth_rate(self, t):
        """Slot 1's certainty-equivalent or scenario-driven return."""
        return if_(
            self.mc_fund_return_source == 0,
            self.reference_forward[t],
            self.fund_1_market_return(t),
        ) * self.live(t)

    def fund_1_additions(self, t):
        """Slot 1's share of the active anniversary additions."""
        return self.additions_pp(t) * if_(
            self.fund_after_charges_total(t) > 0,
            self.fund_1_after_charges(t) / self.fund_after_charges_total(t),
            self.fund_1_allocation(t),
        )

    def fund_1_grown(self, t):
        """Active slot 1 after growth, before its fund management charge."""
        return (self.fund_1_after_charges(t) + self.fund_1_additions(t)) * (
            1 + self.fund_1_growth_rate(t)
        )

    def fund_1_fmc_rate(self, t):
        """Monthly fund management charge rate for slot 1."""
        return (1 - (1 - self.policy.Fund_1_FMC) ** (1 / 12)) * self.live(t)

    def fund_1_fmc(self, t):
        """Fund management charge for active slot 1."""
        return self.fund_1_grown(t) * self.fund_1_fmc_rate(t)

    def fund_1_close(self, t):
        """Closing active value of slot 1 before expected exits."""
        return self.fund_1_grown(t) - self.fund_1_fmc(t)

    def fund_1_topup_close(self, t):
        """Closing value of tagged top-up units before expected exits."""
        return (
            self.fund_1_topup_after_charges(t)
            * (1 + self.fund_1_growth_rate(t))
            * (1 - self.fund_1_fmc_rate(t))
        )

    def fund_1_highest_nav_on(self, t):
        """Whether slot 1 carries the variant's highest-NAV guarantee."""
        return self.policy.V_highest_nav_start_month > 0 and self.policy.Fund_1_Guarantee_Type == 1

    def fund_1_nav_open(self, t):
        """Opening price per unit on this basis and scenario path."""
        return prev(self.fund_1_nav, self.policy.Fund_1_Unit_Price)

    def fund_1_nav(self, t):
        """Closing price per unit, with investment return net of FMC."""
        return if_(
            self.fund_1_highest_nav_on(t) or self.policy.V_topup_on,
            self.fund_1_nav_open(t)
            * (1 + self.fund_1_growth_rate(t))
            * (1 - self.fund_1_fmc_rate(t)),
            self.policy.Fund_1_Unit_Price,
        )

    def fund_1_topup_units(self, t):
        """Quantity of tagged top-up units held at month-end before exits."""
        return if_(self.fund_1_nav(t) > 0, self.fund_1_topup_close(t) / self.fund_1_nav(t), 0)

    def fund_1_highest_nav(self, t):
        """Highest unit price recorded in the contractual guarantee window."""
        return if_(
            self.fund_1_highest_nav_on(t),
            if_(
                self.live(t) and self.policy_month(t) >= self.policy.V_highest_nav_start_month,
                max(
                    prev(self.fund_1_highest_nav, self.policy.Fund_1_Guaranteed_Price),
                    self.fund_1_nav(t),
                ),
                prev(self.fund_1_highest_nav, self.policy.Fund_1_Guaranteed_Price),
            ),
            0,
        )

    def fund_1_nav_excess_per_unit(self, t):
        """The maturity-only shortfall per guaranteed unit."""
        return if_(
            self.maturity(t) and self.fund_1_highest_nav_on(t),
            max(self.fund_1_highest_nav(t) - self.fund_1_nav(t), 0),
            0,
        )

    def fund_1_nav_excess(self, t):
        """The shortfall on the active slot's units before expected maturity exits."""
        return if_(
            self.fund_1_nav_excess_per_unit(t) > 0 and self.fund_1_nav_open(t) > 0,
            self.fund_1_nav_excess_per_unit(t)
            * ((self.fund_1_after_charges(t) + self.fund_1_additions(t)) / self.fund_1_nav_open(t)),
            0,
        )

    def rpu_1_open(self, t):
        """Opening aggregate paid-up holding in slot 1."""
        return prev(self.rpu_1_close, self.policy.Fund_1_Value * (self.policy.Policy_Status == 2))

    def rpu_1_after_charges(self, t):
        """Paid-up slot 1 after its proportional share of charges."""
        return self.rpu_1_open(t) * self.rpu_retention(t)

    def rpu_1_grown(self, t):
        """Paid-up slot 1 after its own investment return."""
        return self.rpu_1_after_charges(t) * (1 + self.fund_1_growth_rate(t))

    def rpu_1_fmc(self, t):
        """Fund management charge for paid-up slot 1."""
        return self.rpu_1_grown(t) * self.fund_1_fmc_rate(t)

    def rpu_1_after_fmc(self, t):
        """Paid-up slot 1 after growth and all charges, before expected exits."""
        return self.rpu_1_grown(t) - self.rpu_1_fmc(t)

    def rpu_1_close(self, t):
        """Surviving paid-up slot 1 plus transfers from active units."""
        return self.rpu_1_after_fmc(t) * self.R_survival(t) + self.to_rpu(t) * self.fund_1_close(t)

    def rpu_1_nav_excess(self, t):
        """The shortfall on aggregate paid-up units before expected maturity exits."""
        return if_(
            self.fund_1_nav_excess_per_unit(t) > 0 and self.fund_1_nav_open(t) > 0,
            self.fund_1_nav_excess_per_unit(t)
            * (self.rpu_1_after_charges(t) / self.fund_1_nav_open(t)),
            0,
        )

    def fund_2_allocation(self, t):
        """Fund 2's share of the allocation weights."""
        return if_(
            self.allocation_total(t) > 0,
            self.policy.Fund_2_Allocation / self.allocation_total(t),
            0,
        )

    def fund_2_raw_open(self, t):
        """Opening active value of slot 2, with rebalancing when due."""
        return if_(
            t == 0 or ((self.live(t) or self.maturity(t)) and self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.fund_close_total, 0) * self.fund_2_allocation(t),
                prev(
                    self.fund_2_close,
                    self.policy.Fund_2_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_2_strategy_member(self, t):
        """Whether slot 2 belongs to the strategy basket."""
        return self.policy.Strategy_Source_Slot == 2 or self.policy.Strategy_Target_2 > 0

    def fund_2_strategy_weight(self, t):
        """Lifecycle target weight within the equity and debt basket."""
        return if_(
            self.policy.Strategy_Source_Slot == 2,
            self.strategy_share(t),
            (1 - self.strategy_share(t)) * self.policy.Strategy_Target_2,
        )

    def fund_2_strategy_change(self, t):
        """Gross lifecycle target minus the opening value in slot 2."""
        return if_(
            self.lifecycle_switch(t) and self.fund_2_strategy_member(t),
            self.strategy_value(t) * self.fund_2_strategy_weight(t) - self.fund_2_raw_open(t),
            0,
        )

    def fund_2_switch_out(self, t):
        """Value sold from slot 2, before the switch charge."""
        return if_(
            self.stp_switch(t) and self.policy.Strategy_Source_Slot == 2,
            if_(
                self.policy.Strategy_Mode == 3,
                self.fund_2_raw_open(t) * self.strategy_share(t),
                min(self.policy.Strategy_Amount, self.fund_2_raw_open(t)),
            ),
            max(-self.fund_2_strategy_change(t), 0),
        )

    def fund_2_switch_weight(self, t):
        """Share of net switch proceeds invested in slot 2."""
        return if_(
            self.lifecycle_switch(t),
            if_(
                self.lifecycle_demand(t) > 0,
                max(self.fund_2_strategy_change(t), 0) / self.lifecycle_demand(t),
                0,
            ),
            self.policy.Strategy_Target_2,
        )

    def fund_2_open(self, t):
        """Opening slot value after internal strategy transfers and their charge."""
        return if_(
            self.switch_out_total(t) > 0,
            self.fund_2_raw_open(t)
            - self.fund_2_switch_out(t)
            + self.switch_net_pp(t) * self.fund_2_switch_weight(t),
            self.fund_2_raw_open(t),
        )

    def fund_2_after_premium(self, t):
        """Slot 2 after crediting its share of allocated premiums."""
        return self.fund_2_open(t) + self.allocated_pp(t) * self.fund_2_allocation(t)

    def fund_2_topup_raw_open(self, t):
        """Opening tagged top-up balance, including its share of any rebalance."""
        return if_(
            self.policy.V_topup_on and (t == 0 or self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.topup_close_total, 0) * self.fund_2_allocation(t),
                prev(
                    self.fund_2_topup_close,
                    self.policy.Fund_2_Topup_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_2_topup_switch_out(self, t):
        """The portion of the sale made up of tagged top-up units."""
        return if_(
            self.fund_2_switch_out(t) > 0 and self.fund_2_raw_open(t) > 0,
            self.fund_2_switch_out(t) * (self.fund_2_topup_raw_open(t) / self.fund_2_raw_open(t)),
            0,
        )

    def fund_2_topup_open(self, t):
        """Opening tagged value after the same transfer and charge as other units."""
        return if_(
            self.switch_out_total(t) > 0 and self.policy.V_topup_on,
            self.fund_2_topup_raw_open(t)
            - self.fund_2_topup_switch_out(t)
            + self.switch_net_pp(t)
            * self.fund_2_switch_weight(t)
            * (self.topup_switch_out_total(t) / self.switch_out_total(t)),
            self.fund_2_topup_raw_open(t),
        )

    def fund_2_topup_after_premium(self, t):
        """Tagged top-up balance after buying new units."""
        return self.fund_2_topup_open(t) + self.allocated_topup_pp(t) * self.fund_2_allocation(t)

    def fund_2_withdrawable(self, t):
        """Slot value available for partial withdrawal."""
        return if_(
            self.topup_lock_active(t),
            max(self.fund_2_after_premium(t) - self.fund_2_topup_after_premium(t), 0),
            self.fund_2_after_premium(t),
        )

    def fund_2_withdrawal(self, t):
        """The withdrawal apportioned by the slot's unlocked holdings."""
        return if_(
            self.withdrawable_total(t) > 0,
            self.pw_pp(t) * (self.fund_2_withdrawable(t) / self.withdrawable_total(t)),
            0,
        )

    def fund_2_after_charges(self, t):
        """Slot 2 after its share of withdrawals and charges."""
        return if_(
            self.topup_lock_active(t),
            (self.fund_2_after_premium(t) - self.fund_2_withdrawal(t))
            * self.retention_after_withdrawal(t),
            self.fund_2_after_premium(t) * self.active_retention(t),
        )

    def fund_2_topup_after_charges(self, t):
        """Top-up units after deductions, valued at the opening price."""
        return self.fund_2_topup_after_premium(t) * if_(
            self.topup_lock_active(t), self.retention_after_withdrawal(t), self.active_retention(t)
        )

    def fund_2_market_return(self, t):
        """Monthly asset-mix return and fund alpha of slot 2."""
        return (
            self.policy.Fund_2_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_2_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_2_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_2_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_2_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_2_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_2_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_2_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_2_W_gold * self.ret_gold[t]
            + self.policy.Fund_2_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_2_Alpha) ** (1 / 12) - 1)

    def fund_2_growth_rate(self, t):
        """Gross investment return for slot 2."""
        return self.fund_2_market_return(t) * self.live(t)

    @on("reserving", overrides="fund_2_growth_rate")
    def fund_2_reserving_growth_rate(self, t):
        """Slot 2's return including the reserving margin."""
        return ((1 + self.fund_2_market_return(t)) * self.fund_return_factor(t) - 1) * self.live(t)

    @on("mc", overrides="fund_2_growth_rate")
    def fund_2_mc_growth_rate(self, t):
        """Slot 2's certainty-equivalent or scenario-driven return."""
        return if_(
            self.mc_fund_return_source == 0,
            self.reference_forward[t],
            self.fund_2_market_return(t),
        ) * self.live(t)

    def fund_2_additions(self, t):
        """Slot 2's share of the active anniversary additions."""
        return self.additions_pp(t) * if_(
            self.fund_after_charges_total(t) > 0,
            self.fund_2_after_charges(t) / self.fund_after_charges_total(t),
            self.fund_2_allocation(t),
        )

    def fund_2_grown(self, t):
        """Active slot 2 after growth, before its fund management charge."""
        return (self.fund_2_after_charges(t) + self.fund_2_additions(t)) * (
            1 + self.fund_2_growth_rate(t)
        )

    def fund_2_fmc_rate(self, t):
        """Monthly fund management charge rate for slot 2."""
        return (1 - (1 - self.policy.Fund_2_FMC) ** (1 / 12)) * self.live(t)

    def fund_2_fmc(self, t):
        """Fund management charge for active slot 2."""
        return self.fund_2_grown(t) * self.fund_2_fmc_rate(t)

    def fund_2_close(self, t):
        """Closing active value of slot 2 before expected exits."""
        return self.fund_2_grown(t) - self.fund_2_fmc(t)

    def fund_2_topup_close(self, t):
        """Closing value of tagged top-up units before expected exits."""
        return (
            self.fund_2_topup_after_charges(t)
            * (1 + self.fund_2_growth_rate(t))
            * (1 - self.fund_2_fmc_rate(t))
        )

    def fund_2_highest_nav_on(self, t):
        """Whether slot 2 carries the variant's highest-NAV guarantee."""
        return self.policy.V_highest_nav_start_month > 0 and self.policy.Fund_2_Guarantee_Type == 1

    def fund_2_nav_open(self, t):
        """Opening price per unit on this basis and scenario path."""
        return prev(self.fund_2_nav, self.policy.Fund_2_Unit_Price)

    def fund_2_nav(self, t):
        """Closing price per unit, with investment return net of FMC."""
        return if_(
            self.fund_2_highest_nav_on(t) or self.policy.V_topup_on,
            self.fund_2_nav_open(t)
            * (1 + self.fund_2_growth_rate(t))
            * (1 - self.fund_2_fmc_rate(t)),
            self.policy.Fund_2_Unit_Price,
        )

    def fund_2_topup_units(self, t):
        """Quantity of tagged top-up units held at month-end before exits."""
        return if_(self.fund_2_nav(t) > 0, self.fund_2_topup_close(t) / self.fund_2_nav(t), 0)

    def fund_2_highest_nav(self, t):
        """Highest unit price recorded in the contractual guarantee window."""
        return if_(
            self.fund_2_highest_nav_on(t),
            if_(
                self.live(t) and self.policy_month(t) >= self.policy.V_highest_nav_start_month,
                max(
                    prev(self.fund_2_highest_nav, self.policy.Fund_2_Guaranteed_Price),
                    self.fund_2_nav(t),
                ),
                prev(self.fund_2_highest_nav, self.policy.Fund_2_Guaranteed_Price),
            ),
            0,
        )

    def fund_2_nav_excess_per_unit(self, t):
        """The maturity-only shortfall per guaranteed unit."""
        return if_(
            self.maturity(t) and self.fund_2_highest_nav_on(t),
            max(self.fund_2_highest_nav(t) - self.fund_2_nav(t), 0),
            0,
        )

    def fund_2_nav_excess(self, t):
        """The shortfall on the active slot's units before expected maturity exits."""
        return if_(
            self.fund_2_nav_excess_per_unit(t) > 0 and self.fund_2_nav_open(t) > 0,
            self.fund_2_nav_excess_per_unit(t)
            * ((self.fund_2_after_charges(t) + self.fund_2_additions(t)) / self.fund_2_nav_open(t)),
            0,
        )

    def rpu_2_open(self, t):
        """Opening aggregate paid-up holding in slot 2."""
        return prev(self.rpu_2_close, self.policy.Fund_2_Value * (self.policy.Policy_Status == 2))

    def rpu_2_after_charges(self, t):
        """Paid-up slot 2 after its proportional share of charges."""
        return self.rpu_2_open(t) * self.rpu_retention(t)

    def rpu_2_grown(self, t):
        """Paid-up slot 2 after its own investment return."""
        return self.rpu_2_after_charges(t) * (1 + self.fund_2_growth_rate(t))

    def rpu_2_fmc(self, t):
        """Fund management charge for paid-up slot 2."""
        return self.rpu_2_grown(t) * self.fund_2_fmc_rate(t)

    def rpu_2_after_fmc(self, t):
        """Paid-up slot 2 after growth and all charges, before expected exits."""
        return self.rpu_2_grown(t) - self.rpu_2_fmc(t)

    def rpu_2_close(self, t):
        """Surviving paid-up slot 2 plus transfers from active units."""
        return self.rpu_2_after_fmc(t) * self.R_survival(t) + self.to_rpu(t) * self.fund_2_close(t)

    def rpu_2_nav_excess(self, t):
        """The shortfall on aggregate paid-up units before expected maturity exits."""
        return if_(
            self.fund_2_nav_excess_per_unit(t) > 0 and self.fund_2_nav_open(t) > 0,
            self.fund_2_nav_excess_per_unit(t)
            * (self.rpu_2_after_charges(t) / self.fund_2_nav_open(t)),
            0,
        )

    def fund_3_allocation(self, t):
        """Fund 3's share of the allocation weights."""
        return if_(
            self.allocation_total(t) > 0,
            self.policy.Fund_3_Allocation / self.allocation_total(t),
            0,
        )

    def fund_3_raw_open(self, t):
        """Opening active value of slot 3, with rebalancing when due."""
        return if_(
            t == 0 or ((self.live(t) or self.maturity(t)) and self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.fund_close_total, 0) * self.fund_3_allocation(t),
                prev(
                    self.fund_3_close,
                    self.policy.Fund_3_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_3_strategy_member(self, t):
        """Whether slot 3 belongs to the strategy basket."""
        return self.policy.Strategy_Source_Slot == 3 or self.policy.Strategy_Target_3 > 0

    def fund_3_strategy_weight(self, t):
        """Lifecycle target weight within the equity and debt basket."""
        return if_(
            self.policy.Strategy_Source_Slot == 3,
            self.strategy_share(t),
            (1 - self.strategy_share(t)) * self.policy.Strategy_Target_3,
        )

    def fund_3_strategy_change(self, t):
        """Gross lifecycle target minus the opening value in slot 3."""
        return if_(
            self.lifecycle_switch(t) and self.fund_3_strategy_member(t),
            self.strategy_value(t) * self.fund_3_strategy_weight(t) - self.fund_3_raw_open(t),
            0,
        )

    def fund_3_switch_out(self, t):
        """Value sold from slot 3, before the switch charge."""
        return if_(
            self.stp_switch(t) and self.policy.Strategy_Source_Slot == 3,
            if_(
                self.policy.Strategy_Mode == 3,
                self.fund_3_raw_open(t) * self.strategy_share(t),
                min(self.policy.Strategy_Amount, self.fund_3_raw_open(t)),
            ),
            max(-self.fund_3_strategy_change(t), 0),
        )

    def fund_3_switch_weight(self, t):
        """Share of net switch proceeds invested in slot 3."""
        return if_(
            self.lifecycle_switch(t),
            if_(
                self.lifecycle_demand(t) > 0,
                max(self.fund_3_strategy_change(t), 0) / self.lifecycle_demand(t),
                0,
            ),
            self.policy.Strategy_Target_3,
        )

    def fund_3_open(self, t):
        """Opening slot value after internal strategy transfers and their charge."""
        return if_(
            self.switch_out_total(t) > 0,
            self.fund_3_raw_open(t)
            - self.fund_3_switch_out(t)
            + self.switch_net_pp(t) * self.fund_3_switch_weight(t),
            self.fund_3_raw_open(t),
        )

