        """Monthly asset-mix return and fund alpha of slot 3."""
        return (
            self.policy.Fund_3_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_3_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_3_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_3_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_3_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_3_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_3_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_3_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_3_W_gold * self.ret_gold[t]
            + self.policy.Fund_3_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_3_Alpha) ** (1 / 12) - 1)

