    def fund_4_after_charges(self, t):
        """Slot 4 after its share of withdrawals and charges."""
        return if_(
            self.topup_lock_active(t),
            (self.fund_4_after_premium(t) - self.fund_4_withdrawal(t))
            * self.retention_after_withdrawal(t),
            self.fund_4_after_premium(t) * self.active_retention(t),
        )

    def fund_4_topup_after_charges(self, t):
        """Top-up units after deductions, valued at the opening price."""
        return self.fund_4_topup_after_premium(t) * if_(
            self.topup_lock_active(t), self.retention_after_withdrawal(t), self.active_retention(t)
        )

    def fund_4_market_return(self, t):
        """Monthly asset-mix return and fund alpha of slot 4."""
        return (
            self.policy.Fund_4_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_4_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_4_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_4_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_4_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_4_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_4_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_4_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_4_W_gold * self.ret_gold[t]
            + self.policy.Fund_4_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_4_Alpha) ** (1 / 12) - 1)

    def fund_4_growth_rate(self, t):
        """Gross investment return for slot 4."""
        return self.fund_4_market_return(t) * self.live(t)

    @on("reserving", overrides="fund_4_growth_rate")
    def fund_4_reserving_growth_rate(self, t):
        """Slot 4's return including the reserving margin."""
        return ((1 + self.fund_4_market_return(t)) * self.fund_return_factor(t) - 1) * self.live(t)

    @on("mc", overrides="fund_4_growth_rate")
    def fund_4_mc_growth_rate(self, t):
        """Slot 4's certainty-equivalent or scenario-driven return."""
        return if_(
            self.mc_fund_return_source == 0,
            self.reference_forward[t],
            self.fund_4_market_return(t),
        ) * self.live(t)

    def fund_4_additions(self, t):
        """Slot 4's share of the active anniversary additions."""
        return self.additions_pp(t) * if_(
            self.fund_after_charges_total(t) > 0,
            self.fund_4_after_charges(t) / self.fund_after_charges_total(t),
            self.fund_4_allocation(t),
        )

    def fund_4_grown(self, t):
        """Active slot 4 after growth, before its fund management charge."""
        return (self.fund_4_after_charges(t) + self.fund_4_additions(t)) * (
            1 + self.fund_4_growth_rate(t)
        )

    def fund_4_fmc_rate(self, t):
        """Monthly fund management charge rate for slot 4."""
        return (1 - (1 - self.policy.Fund_4_FMC) ** (1 / 12)) * self.live(t)

    def fund_4_fmc(self, t):
        """Fund management charge for active slot 4."""
        return self.fund_4_grown(t) * self.fund_4_fmc_rate(t)

    def fund_4_close(self, t):
        """Closing active value of slot 4 before expected exits."""
        return self.fund_4_grown(t) - self.fund_4_fmc(t)

    def fund_4_topup_close(self, t):
        """Closing value of tagged top-up units before expected exits."""
        return (
            self.fund_4_topup_after_charges(t)
            * (1 + self.fund_4_growth_rate(t))
            * (1 - self.fund_4_fmc_rate(t))
        )

    def fund_4_highest_nav_on(self, t):
        """Whether slot 4 carries the variant's highest-NAV guarantee."""
        return self.policy.V_highest_nav_start_month > 0 and self.policy.Fund_4_Guarantee_Type == 1

    def fund_4_nav_open(self, t):
        """Opening price per unit on this basis and scenario path."""
        return prev(self.fund_4_nav, self.policy.Fund_4_Unit_Price)

    def fund_4_nav(self, t):
        """Closing price per unit, with investment return net of FMC."""
        return if_(
            self.fund_4_highest_nav_on(t) or self.policy.V_topup_on,
            self.fund_4_nav_open(t)
            * (1 + self.fund_4_growth_rate(t))
            * (1 - self.fund_4_fmc_rate(t)),
            self.policy.Fund_4_Unit_Price,
        )

    def fund_4_topup_units(self, t):
        """Quantity of tagged top-up units held at month-end before exits."""
        return if_(self.fund_4_nav(t) > 0, self.fund_4_topup_close(t) / self.fund_4_nav(t), 0)

    def fund_4_highest_nav(self, t):
        """Highest unit price recorded in the contractual guarantee window."""
        return if_(
            self.fund_4_highest_nav_on(t),
            if_(
                self.live(t) and self.policy_month(t) >= self.policy.V_highest_nav_start_month,
                max(
                    prev(self.fund_4_highest_nav, self.policy.Fund_4_Guaranteed_Price),
                    self.fund_4_nav(t),
                ),
                prev(self.fund_4_highest_nav, self.policy.Fund_4_Guaranteed_Price),
            ),
            0,
        )

    def fund_4_nav_excess_per_unit(self, t):
        """The maturity-only shortfall per guaranteed unit."""
        return if_(
            self.maturity(t) and self.fund_4_highest_nav_on(t),
            max(self.fund_4_highest_nav(t) - self.fund_4_nav(t), 0),
            0,
        )

    def fund_4_nav_excess(self, t):
        """The shortfall on the active slot's units before expected maturity exits."""
        return if_(
            self.fund_4_nav_excess_per_unit(t) > 0 and self.fund_4_nav_open(t) > 0,
            self.fund_4_nav_excess_per_unit(t)
            * ((self.fund_4_after_charges(t) + self.fund_4_additions(t)) / self.fund_4_nav_open(t)),
            0,
        )

    def rpu_4_open(self, t):
        """Opening aggregate paid-up holding in slot 4."""
        return prev(self.rpu_4_close, self.policy.Fund_4_Value * (self.policy.Policy_Status == 2))

    def rpu_4_after_charges(self, t):
        """Paid-up slot 4 after its proportional share of charges."""
        return self.rpu_4_open(t) * self.rpu_retention(t)

    def rpu_4_grown(self, t):
        """Paid-up slot 4 after its own investment return."""
        return self.rpu_4_after_charges(t) * (1 + self.fund_4_growth_rate(t))

    def rpu_4_fmc(self, t):
        """Fund management charge for paid-up slot 4."""
        return self.rpu_4_grown(t) * self.fund_4_fmc_rate(t)

    def rpu_4_after_fmc(self, t):
        """Paid-up slot 4 after growth and all charges, before expected exits."""
        return self.rpu_4_grown(t) - self.rpu_4_fmc(t)

    def rpu_4_close(self, t):
        """Surviving paid-up slot 4 plus transfers from active units."""
        return self.rpu_4_after_fmc(t) * self.R_survival(t) + self.to_rpu(t) * self.fund_4_close(t)

    def rpu_4_nav_excess(self, t):
        """The shortfall on aggregate paid-up units before expected maturity exits."""
        return if_(
            self.fund_4_nav_excess_per_unit(t) > 0 and self.fund_4_nav_open(t) > 0,
            self.fund_4_nav_excess_per_unit(t)
            * (self.rpu_4_after_charges(t) / self.fund_4_nav_open(t)),
            0,
        )

    def fund_5_allocation(self, t):
        """Fund 5's share of the allocation weights."""
        return if_(
            self.allocation_total(t) > 0,
            self.policy.Fund_5_Allocation / self.allocation_total(t),
            0,
        )

    def fund_5_raw_open(self, t):
        """Opening active value of slot 5, with rebalancing when due."""
        return if_(
            t == 0 or ((self.live(t) or self.maturity(t)) and self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.fund_close_total, 0) * self.fund_5_allocation(t),
                prev(
                    self.fund_5_close,
                    self.policy.Fund_5_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_5_strategy_member(self, t):
        """Whether slot 5 belongs to the strategy basket."""
        return self.policy.Strategy_Source_Slot == 5 or self.policy.Strategy_Target_5 > 0

    def fund_5_strategy_weight(self, t):
        """Lifecycle target weight within the equity and debt basket."""
        return if_(
            self.policy.Strategy_Source_Slot == 5,
            self.strategy_share(t),
            (1 - self.strategy_share(t)) * self.policy.Strategy_Target_5,
        )

    def fund_5_strategy_change(self, t):
        """Gross lifecycle target minus the opening value in slot 5."""
        return if_(
            self.lifecycle_switch(t) and self.fund_5_strategy_member(t),
            self.strategy_value(t) * self.fund_5_strategy_weight(t) - self.fund_5_raw_open(t),
            0,
        )

    def fund_5_switch_out(self, t):
        """Value sold from slot 5, before the switch charge."""
        return if_(
            self.stp_switch(t) and self.policy.Strategy_Source_Slot == 5,
            if_(
                self.policy.Strategy_Mode == 3,
                self.fund_5_raw_open(t) * self.strategy_share(t),
                min(self.policy.Strategy_Amount, self.fund_5_raw_open(t)),
            ),
            max(-self.fund_5_strategy_change(t), 0),
        )

    def fund_5_switch_weight(self, t):
        """Share of net switch proceeds invested in slot 5."""
        return if_(
            self.lifecycle_switch(t),
            if_(
                self.lifecycle_demand(t) > 0,
                max(self.fund_5_strategy_change(t), 0) / self.lifecycle_demand(t),
                0,
            ),
            self.policy.Strategy_Target_5,
        )

    def fund_5_open(self, t):
        """Opening slot value after internal strategy transfers and their charge."""
        return if_(
            self.switch_out_total(t) > 0,
            self.fund_5_raw_open(t)
            - self.fund_5_switch_out(t)
            + self.switch_net_pp(t) * self.fund_5_switch_weight(t),
            self.fund_5_raw_open(t),
        )

    def fund_5_after_premium(self, t):
        """Slot 5 after crediting its share of allocated premiums."""
        return self.fund_5_open(t) + self.allocated_pp(t) * self.fund_5_allocation(t)

    def fund_5_topup_raw_open(self, t):
        """Opening tagged top-up balance, including its share of any rebalance."""
        return if_(
            self.policy.V_topup_on and (t == 0 or self.A_begin(t) > 0),
            if_(
                self.rebalance(t),
                prev(self.topup_close_total, 0) * self.fund_5_allocation(t),
                prev(
                    self.fund_5_topup_close,
                    self.policy.Fund_5_Topup_Value * (self.policy.Policy_Status == 0),
                ),
            ),
            0,
        )

    def fund_5_topup_switch_out(self, t):
        """The portion of the sale made up of tagged top-up units."""
        return if_(
            self.fund_5_switch_out(t) > 0 and self.fund_5_raw_open(t) > 0,
            self.fund_5_switch_out(t) * (self.fund_5_topup_raw_open(t) / self.fund_5_raw_open(t)),
            0,
        )

    def fund_5_topup_open(self, t):
        """Opening tagged value after the same transfer and charge as other units."""
        return if_(
            self.switch_out_total(t) > 0 and self.policy.V_topup_on,
            self.fund_5_topup_raw_open(t)
            - self.fund_5_topup_switch_out(t)
            + self.switch_net_pp(t)
            * self.fund_5_switch_weight(t)
            * (self.topup_switch_out_total(t) / self.switch_out_total(t)),
            self.fund_5_topup_raw_open(t),
        )

    def fund_5_topup_after_premium(self, t):
        """Tagged top-up balance after buying new units."""
        return self.fund_5_topup_open(t) + self.allocated_topup_pp(t) * self.fund_5_allocation(t)

    def fund_5_withdrawable(self, t):
        """Slot value available for partial withdrawal."""
        return if_(
            self.topup_lock_active(t),
            max(self.fund_5_after_premium(t) - self.fund_5_topup_after_premium(t), 0),
            self.fund_5_after_premium(t),
        )

    def fund_5_withdrawal(self, t):
        """The withdrawal apportioned by the slot's unlocked holdings."""
        return if_(
            self.withdrawable_total(t) > 0,
            self.pw_pp(t) * (self.fund_5_withdrawable(t) / self.withdrawable_total(t)),
            0,
        )

    def fund_5_after_charges(self, t):
        """Slot 5 after its share of withdrawals and charges."""
        return if_(
            self.topup_lock_active(t),
            (self.fund_5_after_premium(t) - self.fund_5_withdrawal(t))
            * self.retention_after_withdrawal(t),
            self.fund_5_after_premium(t) * self.active_retention(t),
        )

    def fund_5_topup_after_charges(self, t):
        """Top-up units after deductions, valued at the opening price."""
        return self.fund_5_topup_after_premium(t) * if_(
            self.topup_lock_active(t), self.retention_after_withdrawal(t), self.active_retention(t)
        )

    def fund_5_market_return(self, t):
        """Monthly asset-mix return and fund alpha of slot 5."""
        return (
            self.policy.Fund_5_W_eq_large * self.ret_eq_large[t]
            + self.policy.Fund_5_W_eq_mid * self.ret_eq_mid[t]
            + self.policy.Fund_5_W_eq_small * self.ret_eq_small[t]
            + self.policy.Fund_5_W_eq_global * self.ret_eq_global[t]
            + self.policy.Fund_5_W_gov_long * self.ret_gov_long[t]
            + self.policy.Fund_5_W_gov_short * self.ret_gov_short[t]
            + self.policy.Fund_5_W_corp_bond * self.ret_corp_bond[t]
            + self.policy.Fund_5_W_money_market * self.ret_money_market[t]
            + self.policy.Fund_5_W_gold * self.ret_gold[t]
            + self.policy.Fund_5_W_real_assets * self.ret_real_assets[t]
        ) + ((1 + self.policy.Fund_5_Alpha) ** (1 / 12) - 1)

    def fund_5_growth_rate(self, t):
        """Gross investment return for slot 5."""
        return self.fund_5_market_return(t) * self.live(t)

    @on("reserving", overrides="fund_5_growth_rate")
    def fund_5_reserving_growth_rate(self, t):
        """Slot 5's return including the reserving margin."""
        return ((1 + self.fund_5_market_return(t)) * self.fund_return_factor(t) - 1) * self.live(t)

    @on("mc", overrides="fund_5_growth_rate")
    def fund_5_mc_growth_rate(self, t):
        """Slot 5's certainty-equivalent or scenario-driven return."""
        return if_(
            self.mc_fund_return_source == 0,
            self.reference_forward[t],
            self.fund_5_market_return(t),
        ) * self.live(t)

    def fund_5_additions(self, t):
        """Slot 5's share of the active anniversary additions."""
        return self.additions_pp(t) * if_(
            self.fund_after_charges_total(t) > 0,
            self.fund_5_after_charges(t) / self.fund_after_charges_total(t),
            self.fund_5_allocation(t),
        )

    def fund_5_grown(self, t):
        """Active slot 5 after growth, before its fund management charge."""
        return (self.fund_5_after_charges(t) + self.fund_5_additions(t)) * (
            1 + self.fund_5_growth_rate(t)
        )

    def fund_5_fmc_rate(self, t):
        """Monthly fund management charge rate for slot 5."""
        return (1 - (1 - self.policy.Fund_5_FMC) ** (1 / 12)) * self.live(t)

    def fund_5_fmc(self, t):
        """Fund management charge for active slot 5."""
        return self.fund_5_grown(t) * self.fund_5_fmc_rate(t)

    def fund_5_close(self, t):
        """Closing active value of slot 5 before expected exits."""
        return self.fund_5_grown(t) - self.fund_5_fmc(t)

    def fund_5_topup_close(self, t):
        """Closing value of tagged top-up units before expected exits."""
        return (
            self.fund_5_topup_after_charges(t)
            * (1 + self.fund_5_growth_rate(t))
            * (1 - self.fund_5_fmc_rate(t))
        )

    def fund_5_highest_nav_on(self, t):
        """Whether slot 5 carries the variant's highest-NAV guarantee."""
        return self.policy.V_highest_nav_start_month > 0 and self.policy.Fund_5_Guarantee_Type == 1

    def fund_5_nav_open(self, t):
        """Opening price per unit on this basis and scenario path."""
        return prev(self.fund_5_nav, self.policy.Fund_5_Unit_Price)

    def fund_5_nav(self, t):
        """Closing price per unit, with investment return net of FMC."""
        return if_(
            self.fund_5_highest_nav_on(t) or self.policy.V_topup_on,
            self.fund_5_nav_open(t)
            * (1 + self.fund_5_growth_rate(t))
            * (1 - self.fund_5_fmc_rate(t)),
            self.policy.Fund_5_Unit_Price,
        )

    def fund_5_topup_units(self, t):
        """Quantity of tagged top-up units held at month-end before exits."""
        return if_(self.fund_5_nav(t) > 0, self.fund_5_topup_close(t) / self.fund_5_nav(t), 0)

    def fund_5_highest_nav(self, t):
        """Highest unit price recorded in the contractual guarantee window."""
        return if_(
            self.fund_5_highest_nav_on(t),
            if_(
                self.live(t) and self.policy_month(t) >= self.policy.V_highest_nav_start_month,
                max(
                    prev(self.fund_5_highest_nav, self.policy.Fund_5_Guaranteed_Price),
                    self.fund_5_nav(t),
                ),
                prev(self.fund_5_highest_nav, self.policy.Fund_5_Guaranteed_Price),
            ),
            0,
        )

    def fund_5_nav_excess_per_unit(self, t):
        """The maturity-only shortfall per guaranteed unit."""
        return if_(
            self.maturity(t) and self.fund_5_highest_nav_on(t),
            max(self.fund_5_highest_nav(t) - self.fund_5_nav(t), 0),
            0,
        )

    def fund_5_nav_excess(self, t):
        """The shortfall on the active slot's units before expected maturity exits."""
        return if_(
            self.fund_5_nav_excess_per_unit(t) > 0 and self.fund_5_nav_open(t) > 0,
            self.fund_5_nav_excess_per_unit(t)
            * ((self.fund_5_after_charges(t) + self.fund_5_additions(t)) / self.fund_5_nav_open(t)),
            0,
        )

    def rpu_5_open(self, t):
        """Opening aggregate paid-up holding in slot 5."""
        return prev(self.rpu_5_close, self.policy.Fund_5_Value * (self.policy.Policy_Status == 2))

    def rpu_5_after_charges(self, t):
        """Paid-up slot 5 after its proportional share of charges."""
        return self.rpu_5_open(t) * self.rpu_retention(t)

    def rpu_5_grown(self, t):
        """Paid-up slot 5 after its own investment return."""
        return self.rpu_5_after_charges(t) * (1 + self.fund_5_growth_rate(t))

    def rpu_5_fmc(self, t):
        """Fund management charge for paid-up slot 5."""
        return self.rpu_5_grown(t) * self.fund_5_fmc_rate(t)

    def rpu_5_after_fmc(self, t):
        """Paid-up slot 5 after growth and all charges, before expected exits."""
        return self.rpu_5_grown(t) - self.rpu_5_fmc(t)

    def rpu_5_close(self, t):
        """Surviving paid-up slot 5 plus transfers from active units."""
        return self.rpu_5_after_fmc(t) * self.R_survival(t) + self.to_rpu(t) * self.fund_5_close(t)

    def rpu_5_nav_excess(self, t):
        """The shortfall on aggregate paid-up units before expected maturity exits."""
        return if_(
            self.fund_5_nav_excess_per_unit(t) > 0 and self.fund_5_nav_open(t) > 0,
            self.fund_5_nav_excess_per_unit(t)
            * (self.rpu_5_after_charges(t) / self.fund_5_nav_open(t)),
            0,
        )

    def nav_excess_A_pp(self, t):
        """Highest-NAV excess per active life."""
        return (
            self.fund_1_nav_excess(t)
            + self.fund_2_nav_excess(t)
            + self.fund_3_nav_excess(t)
            + self.fund_4_nav_excess(t)
            + self.fund_5_nav_excess(t)
        )

    def nav_excess_R(self, t):
        """Highest-NAV excess on aggregate opening paid-up lives."""
        return (
            self.rpu_1_nav_excess(t)
            + self.rpu_2_nav_excess(t)
            + self.rpu_3_nav_excess(t)
            + self.rpu_4_nav_excess(t)
            + self.rpu_5_nav_excess(t)
        )

    def strategy_value(self, t):
        """Opening value within the strategy basket."""
        return (
            self.fund_1_raw_open(t) * self.fund_1_strategy_member(t)
            + self.fund_2_raw_open(t) * self.fund_2_strategy_member(t)
            + self.fund_3_raw_open(t) * self.fund_3_strategy_member(t)
            + self.fund_4_raw_open(t) * self.fund_4_strategy_member(t)
            + self.fund_5_raw_open(t) * self.fund_5_strategy_member(t)
        )

    def lifecycle_demand(self, t):
        """Gross lifecycle purchases requested."""
        return (
            max(self.fund_1_strategy_change(t), 0)
            + max(self.fund_2_strategy_change(t), 0)
            + max(self.fund_3_strategy_change(t), 0)
            + max(self.fund_4_strategy_change(t), 0)
            + max(self.fund_5_strategy_change(t), 0)
        )

    def switch_out_total(self, t):
        """Gross sales from all slots."""
        return (
            self.fund_1_switch_out(t)
            + self.fund_2_switch_out(t)
            + self.fund_3_switch_out(t)
            + self.fund_4_switch_out(t)
            + self.fund_5_switch_out(t)
        )

    def topup_switch_out_total(self, t):
        """Tagged portion of gross sales."""
        return (
            self.fund_1_topup_switch_out(t)
            + self.fund_2_topup_switch_out(t)
            + self.fund_3_topup_switch_out(t)
            + self.fund_4_topup_switch_out(t)
            + self.fund_5_topup_switch_out(t)
        )

    def fund_fmc_total(self, t):
        """Total active FMC per life."""
        return (
            self.fund_1_fmc(t)
            + self.fund_2_fmc(t)
            + self.fund_3_fmc(t)
            + self.fund_4_fmc(t)
            + self.fund_5_fmc(t)
        )

    def rpu_open_total(self, t):
        """Total paid-up funds at the open stage."""
        return (
            self.rpu_1_open(t)
            + self.rpu_2_open(t)
            + self.rpu_3_open(t)
            + self.rpu_4_open(t)
            + self.rpu_5_open(t)
        )

    def rpu_fmc_total(self, t):
        """Total paid-up funds at the fmc stage."""
        return (
            self.rpu_1_fmc(t)
            + self.rpu_2_fmc(t)
            + self.rpu_3_fmc(t)
            + self.rpu_4_fmc(t)
            + self.rpu_5_fmc(t)
        )

    def rpu_after_fmc_total(self, t):
        """Total paid-up funds at the after fmc stage."""
        return (
            self.rpu_1_after_fmc(t)
            + self.rpu_2_after_fmc(t)
            + self.rpu_3_after_fmc(t)
            + self.rpu_4_after_fmc(t)
            + self.rpu_5_after_fmc(t)
        )

    def rpu_close_total(self, t):
        """Total paid-up funds at the close stage."""
        return (
            self.rpu_1_close(t)
            + self.rpu_2_close(t)
            + self.rpu_3_close(t)
            + self.rpu_4_close(t)
            + self.rpu_5_close(t)
        )

    def opening_unit_fund(self, t):
        """All non-DPF holdings at valuation."""
        return (
            self.policy.Fund_1_Value
            + self.policy.Fund_2_Value
            + self.policy.Fund_3_Value
            + self.policy.Fund_4_Value
            + self.policy.Fund_5_Value
        ) * (t == 0)

    def allocation_total(self, t):
        """Sum of policy allocation weights."""
        return (
            self.policy.Fund_1_Allocation
            + self.policy.Fund_2_Allocation
            + self.policy.Fund_3_Allocation
            + self.policy.Fund_4_Allocation
            + self.policy.Fund_5_Allocation
        )

    def fund_open_total(self, t):
        """Total active fund at the open stage."""
        return (
            self.fund_1_open(t)
            + self.fund_2_open(t)
            + self.fund_3_open(t)
            + self.fund_4_open(t)
            + self.fund_5_open(t)
        )

    def fund_after_premium_total(self, t):
        """Total active fund at the after premium stage."""
        return (
            self.fund_1_after_premium(t)
            + self.fund_2_after_premium(t)
            + self.fund_3_after_premium(t)
            + self.fund_4_after_premium(t)
            + self.fund_5_after_premium(t)
        )

    def fund_after_charges_total(self, t):
        """Total active fund at the after charges stage."""
        return (
            self.fund_1_after_charges(t)
            + self.fund_2_after_charges(t)
            + self.fund_3_after_charges(t)
            + self.fund_4_after_charges(t)
            + self.fund_5_after_charges(t)
        )

    def fund_close_total(self, t):
        """Total active fund at the close stage."""
        return (
            self.fund_1_close(t)
            + self.fund_2_close(t)
            + self.fund_3_close(t)
            + self.fund_4_close(t)
            + self.fund_5_close(t)
        )

    def fund_growth_total(self, t):
        """Investment return credited to the active slots per life."""
        return (
            (self.fund_1_after_charges(t) + self.fund_1_additions(t)) * self.fund_1_growth_rate(t)
            + (self.fund_2_after_charges(t) + self.fund_2_additions(t)) * self.fund_2_growth_rate(t)
            + (self.fund_3_after_charges(t) + self.fund_3_additions(t)) * self.fund_3_growth_rate(t)
            + (self.fund_4_after_charges(t) + self.fund_4_additions(t)) * self.fund_4_growth_rate(t)
            + (self.fund_5_after_charges(t) + self.fund_5_additions(t)) * self.fund_5_growth_rate(t)
        )

    def rpu_growth_total(self, t):
        """Investment return credited to the opening paid-up slots."""
        return (
            self.rpu_1_after_charges(t) * self.fund_1_growth_rate(t)
            + self.rpu_2_after_charges(t) * self.fund_2_growth_rate(t)
            + self.rpu_3_after_charges(t) * self.fund_3_growth_rate(t)
            + self.rpu_4_after_charges(t) * self.fund_4_growth_rate(t)
            + self.rpu_5_after_charges(t) * self.fund_5_growth_rate(t)
        )

    def topup_close_total(self, t):
        """Total tagged top-up fund at close."""
        return (
            self.fund_1_topup_close(t)
            + self.fund_2_topup_close(t)
            + self.fund_3_topup_close(t)
            + self.fund_4_topup_close(t)
            + self.fund_5_topup_close(t)
        )

    def withdrawable_total(self, t):
        """Unlocked active funds after premium."""
        return (
            self.fund_1_withdrawable(t)
            + self.fund_2_withdrawable(t)
            + self.fund_3_withdrawable(t)
            + self.fund_4_withdrawable(t)
            + self.fund_5_withdrawable(t)
        )
